// gear.js — the GEAR workshop catalog and its rules, as data. Pure; no DOM.
//
// Every number the economy runs on is in GEAR_RULES, and the same values are
// seeded into Postgres (supabase/migrations/0014_gear.sql, generated by
// tools/gear-sql.mjs) so the client and the server can't disagree. The
// design and the reasoning behind each number are in docs/GEAR.md.
//
// Each discipline has four slots; each slot has a free starter (tier 0) that
// everyone owns and three tiers to buy. A tier is an entry:
//   { id, kind: 'gear', sport, slot, tier, name, blurb, cost, boostBp, art }
// Boosts are in basis points (100 = +1%) so JS and SQL do the same integer
// maths. Kits are colourways for the athlete on the Profile scene: cosmetic,
// no boost. A gel is the one consumable.

import { t } from './i18n.js';

/** Sessions and missions dated before this earn nothing (everyone starts with the purse). */
export const GEAR_SINCE = '2026-11-02';

/**
 * Fuel: consumables bought with carbs. Each one boosts every session inside
 * its window (prorated at the edges). Only one fuel runs at a time, and each
 * kind has its own limit in any rolling 7 days.
 */
const FUEL_ITEMS = {
  gel: { boostBp: 3000, hours: 4, perWindow: 2, cost: 120, maxHeld: 3 },          // +30% for 4 h
  'energy-bar': { boostBp: 1500, hours: 6, perWindow: 2, cost: 80, maxHeld: 3 },  // +15% for 6 h
  pasta: { boostBp: 1000, hours: 12, perWindow: 1, cost: 150, maxHeld: 2 },       // +10% for 12 h
};

export const GEAR_RULES = {
  // two currencies, both earned only by training (and missions), each stored up to a cap
  storageCap: 10000,        // coins and grams of carbs; anything earned past a full store is lost
  coinsPerXp: 0.5,          // coins for a day = floor(that day's base XP × this)…
  dailyCoinCap: 120,        // …at most this many
  carbsPerXp: 0.8,          // grams of carbs for a day = floor(that day's base XP × this)…
  dailyCarbCap: 300,        // …at most this many
  starterPurse: 300,        // everyone's opening coins, once
  starterCarbs: 200,        // and opening carbs
  tierCost: [0, 100, 350, 850],    // coins
  tierBoostBp: [0, 100, 200, 400], // per item, cumulative: +1% / +2% / +4%
  sportCapBp: 1600,         // a discipline's gear boost never exceeds +16% (= a full kit)
  fuel: { windowDays: 7, graceHours: 24, items: FUEL_ITEMS },
  gel: { ...FUEL_ITEMS.gel, windowDays: 7, graceHours: 24 }, // the gel on its own, for the countdown
  kitCost: 250,             // coins
};

/** What each mission pays, in coins or grams of carbs (on top of its XP). */
export const QUEST_REWARDS = {
  'plan-done': { coins: 25 },
  'min-45': { carbs: 30 },
  'two-disc': { coins: 35 },
  streak: { carbs: 20 },
  'km-10': { carbs: 25 },
  brick: { coins: 35 },
  'pack-bag': { carbs: 10 },
  'rest-day': { carbs: 15 },
};

export const SPORTS = ['bike', 'swim', 'run', 'gym'];

/** The four slots of each discipline, in display order. */
export const SLOTS = {
  bike: ['wheels', 'aerobars', 'frame', 'power'],
  swim: ['goggles', 'paddles', 'buoy', 'wetsuit'],
  run: ['shoes', 'watch', 'kit', 'recovery'],
  gym: ['belt', 'shoes', 'sleeves', 'bar'],
};

/** Pixel icon used for each slot until the real art lands (js/core/icons.js names). */
export const SLOT_ICON = {
  'bike-wheels': 'bike', 'bike-aerobars': 'bike', 'bike-frame': 'bike', 'bike-power': 'bolt',
  'swim-goggles': 'swim', 'swim-paddles': 'swim', 'swim-buoy': 'swim', 'swim-wetsuit': 'swim',
  'run-shoes': 'run', 'run-watch': 'clock', 'run-kit': 'run', 'run-recovery': 'heart',
  'gym-belt': 'gym', 'gym-shoes': 'gym', 'gym-sleeves': 'gym', 'gym-bar': 'gym',
};

export const slotId = (sport, slot) => `${sport}-${slot}`;
export const tierId = (sport, slot, tier) => `${slotId(sport, slot)}-t${tier}`;

function tierEntry(sport, slot, tier) {
  const sid = slotId(sport, slot);
  return {
    id: tierId(sport, slot, tier),
    kind: 'gear',
    sport,
    slot,
    tier,
    get name() { return t(`gear.item.${sid}.t${tier}`); },
    get blurb() { return t(`gear.item.${sid}.blurb`); },
    get slotName() { return t(`gear.item.${sid}.slot`); },
    cost: GEAR_RULES.tierCost[tier],
    boostBp: GEAR_RULES.tierBoostBp[tier],
    art: `icons/Pixelart/GEAR/${sid}-t${tier}.png`,
  };
}

/** Every gear tier, starters included: 4 disciplines × 4 slots × tiers 0–3. */
export const CATALOG = SPORTS.flatMap((sport) => SLOTS[sport].flatMap((slot) =>
  [0, 1, 2, 3].map((tier) => tierEntry(sport, slot, tier))));

const BY_ID = new Map(CATALOG.map((e) => [e.id, e]));
export const gearById = (id) => BY_ID.get(id) || null;

/**
 * Kit colourways. Each part is a ramp of four colours, darkest to lightest,
 * that tools/kit-variants.mjs maps onto the tagged palette entries of every
 * character sprite (icons/Pixelart/<SPORT>/CHARACTERS/ramps.json).
 * Placeholder colours until the MOSKE shop colourways are confirmed.
 */
export const KITS = [
  {
    id: 'kit-moske-navy',
    kind: 'kit',
    get name() { return t('gear.kit.moske-navy'); },
    cost: GEAR_RULES.kitCost,
    placeholder: true,
    ramps: {
      jersey: ['#0b1630', '#16264d', '#24396e', '#3a5592'],
      shorts: ['#08080c', '#15151c', '#24242e', '#383844'],
      shoes: ['#6b4a12', '#a8771c', '#d9a52c', '#f2cf63'],
    },
  },
  {
    id: 'kit-moske-sand',
    kind: 'kit',
    get name() { return t('gear.kit.moske-sand'); },
    cost: GEAR_RULES.kitCost,
    placeholder: true,
    ramps: {
      jersey: ['#7a6446', '#a88b62', '#cdb284', '#ead6ad'],
      shorts: ['#1d2a3a', '#2c3d52', '#3f566f', '#58728d'],
      shoes: ['#c9c9c9', '#e0e0e0', '#efefef', '#ffffff'],
    },
  },
];
export const kitById = (id) => KITS.find((k) => k.id === id) || null;
export const kitArt = (id) => `icons/Pixelart/GEAR/${id}.png`;

/**
 * Character sprites that have a recoloured version for a kit
 * (tools/kit-recolor.py writes `<base>--<kitId>.webp` next to the base).
 * A level without one shows the base kit.
 */
export const KIT_SPRITES = {
  'kit-moske-sand': ['icons/Pixelart/BIKE/CHARACTERS/bikelvl6_char.webp'],
};
/** The character sprite to show for a level's base sprite and the kit worn. */
export const kitSprite = (src, kitId) => (kitId && KIT_SPRITES[kitId]?.includes(src) ? src.replace(/\.webp$/, `--${kitId}.webp`) : src);

/** Fuel you buy with carbs: a gel, an energy bar, a pasta meal. */
export const FUELS = Object.entries(FUEL_ITEMS).map(([id, f]) => ({
  id,
  kind: id === 'gel' ? 'gel' : 'food',
  currency: 'carbs',
  get name() { return t(`gear.fuel.${id}.name`); },
  ...f,
  art: `icons/Pixelart/GEAR/fuel-${id}.png`,
}));
export const fuelById = (id) => FUELS.find((f) => f.id === id) || null;
export const GEL = fuelById('gel');

/** Which currency an item costs. */
export const currencyOf = (item) => (item?.currency || (fuelById(item?.id) ? 'carbs' : 'coins'));

/** Everything that can be bought, as plain rows (what 0015 seeds into gear_catalog). */
export function catalogRows() {
  return [
    ...CATALOG.map((e) => ({ id: e.id, kind: 'gear', sport: e.sport, slot: e.slot, tier: e.tier, cost: e.cost, boost_bp: e.boostBp, currency: 'coins' })),
    ...KITS.map((k) => ({ id: k.id, kind: 'kit', sport: null, slot: null, tier: null, cost: k.cost, boost_bp: 0, currency: 'coins' })),
    ...FUELS.map((f) => ({ id: f.id, kind: f.kind, sport: null, slot: null, tier: null, cost: f.cost, boost_bp: f.boostBp, currency: 'carbs' })),
  ];
}

const ms = (s) => {
  const x = Date.parse(s);
  return Number.isFinite(x) ? x : null;
};

/**
 * The tier of one slot owned at a moment (default: now, i.e. anything ever
 * acquired). `inventory` is [{ item_id, acquired_at }] as the server returns it.
 */
export function ownedTier(inventory, sport, slot, at = null) {
  const atMs = at == null ? Infinity : ms(at);
  let best = 0;
  for (const row of inventory || []) {
    const e = gearById(row?.item_id);
    if (!e || e.sport !== sport || e.slot !== slot) continue;
    const got = ms(row.acquired_at);
    if (atMs !== Infinity && (got == null || got > atMs)) continue;
    if (e.tier > best) best = e.tier;
  }
  return best;
}

/** What the next purchase for a slot would be, or null when it's maxed. */
export function nextTier(inventory, sport, slot) {
  const cur = ownedTier(inventory, sport, slot);
  return cur >= 3 ? null : gearById(tierId(sport, slot, cur + 1));
}

/** Kits owned (any time). */
export const ownedKits = (inventory) => KITS.filter((k) => (inventory || []).some((r) => r?.item_id === k.id));
